    parents_goal = {goal: None}
    while q_start and q_goal:
        if q_start:
            for _ in range(len(q_start)):
                r, c = q_start.popleft()
                for nr, nc in neighbors(r, c):
                    if (nr, nc) not in parents_start:
                        parents_start[nr, nc] = (r, c)
                        q_start.append((nr, nc))
                        if (nr, nc) in parents_goal:
