        if q_goal:
            for _ in range(len(q_goal)):
                r, c = q_goal.popleft()
                for nr, nc in neighbors(r, c):
                    if (nr, nc) not in parents_goal:
                        parents_goal[nr, nc] = (r, c)
                        q_goal.append((nr, nc))
