def reconstruct_path(ps, pg, meet, start, goal):
    path_start = []
    node = meet
    while node != start:
        path_start.append(node)
        node = ps[node]
    path_start.reverse()
    path_goal = []
    node = meet
    while node != goal:
        node = pg[node]
        path_goal.append(node)
    return [start] + path_start + path_goal

